package com.shopsphere.service;
import com.shopsphere.dto.AuthDtos.*; import com.shopsphere.entity.*; import com.shopsphere.exception.ApiException; import com.shopsphere.repository.*; import com.shopsphere.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService { private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; private final CartRepository carts; public AuthService(UserRepository users,PasswordEncoder encoder,JwtService jwt,CartRepository carts){this.users=users;this.encoder=encoder;this.jwt=jwt;this.carts=carts;}
 @Transactional public UserResponse register(RegisterRequest r){if(users.existsByEmailIgnoreCase(r.email()))throw new ApiException("EMAIL_EXISTS","Email already registered"); User u=new User();u.setName(r.name());u.setEmail(r.email().toLowerCase());u.setPasswordHash(encoder.encode(r.password()));users.save(u);Cart c=new Cart();c.setUser(u);carts.save(c);return response(u);}
 @Transactional(readOnly=true) public TokenResponse login(LoginRequest r){User u=users.findByEmailIgnoreCase(r.email()).orElseThrow(()->new ApiException("INVALID_CREDENTIALS","Invalid email or password"));if(!encoder.matches(r.password(),u.getPasswordHash()))throw new ApiException("INVALID_CREDENTIALS","Invalid email or password");return new TokenResponse(jwt.generate(u.getId(),u.getEmail(),u.getRole().name()),"Bearer",jwt.expirationSeconds());}
 private UserResponse response(User u){return new UserResponse(u.getId(),u.getName(),u.getEmail(),u.getRole().name());}
}
